package com.adesa.attendance.vendor;
import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;import com.adesa.attendance.mail.MailService;
@Component
public class VendorMail {
 private final VendorService s;private final TransactionTemplate tx;private final MailService mail;private final boolean enabled,approved;
 public VendorMail(VendorService s,VendorTransactions transactions,MailService mail,@Value("${vendor.mail.enabled:false}")boolean enabled,@Value("${vendor.mail.live-approved:false}")boolean approved){this.s=s;this.tx=transactions.template();this.mail=mail;this.enabled=enabled;this.approved=approved;}
 @Scheduled(fixedDelayString="${vendor.mail.interval-ms:30000}") public void dispatch(){if(!enabled||!approved||s.isDemo()||!mail.isDeliveryEnabled())return;for(int n=0;n<10;n++){
  var row=tx.execute(t->{s.context("access","ADMIN");var rows=s.jdbc().queryForList("select * from vendor_private.outbox where state='PREVIEW' order by created_at for update skip locked limit 1");if(rows.isEmpty())return null;var r=rows.getFirst();String recipient=new String(s.crypt().open((byte[])r.get("recipient_cipher"),"recipient:"+r.get("id")),StandardCharsets.UTF_8);if(Boolean.TRUE.equals(r.get("internal"))&&s.jdbc().queryForObject("select count(*) from employees where role='ADMIN' and is_active and lower(email)=?",Integer.class,recipient.toLowerCase(Locale.ROOT))==0){s.jdbc().update("update vendor_private.outbox set state='SUPPRESSED' where id=?",r.get("id"));return Map.<String,Object>of("suppressed",true);}s.jdbc().update("update vendor_private.outbox set state='REVIEW' where id=?",r.get("id"));return r;});if(row==null)return;if(row.containsKey("suppressed"))continue;
  try{String to=new String(s.crypt().open((byte[])row.get("recipient_cipher"),"recipient:"+row.get("id")),StandardCharsets.UTF_8),body=new String(s.crypt().open((byte[])row.get("body_cipher"),"outbox:"+row.get("id")),StandardCharsets.UTF_8);mail.send(to,String.valueOf(row.get("subject")),body,"<div style='font-family:Arial;background:#f7f8fa;padding:30px;color:#11243f'><h1>ADESA Holdings</h1><h2>Vendor Acquisition</h2><p style='white-space:pre-wrap'>"+body.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")+"</p></div>");tx.executeWithoutResult(t->{s.context("access","ADMIN");s.jdbc().update("update vendor_private.outbox set state='DELIVERED',delivered_at=now() where id=?",row.get("id"));});}catch(RuntimeException ignored){/* Reconcile ambiguous delivery with the provider; never automatically resend. */}
 }}
}
